responsePreview:
This Terraform configuration creates a DynamoDB global table with a primary table in `us-east-1` and replicas in `us-west-1` and `us-west-2`. The table uses on-demand billing, has a simple string partition key, and enables DynamoDB Streams as required for global table replication.

```hcl
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.primary_region
}

variable "primary_region" {
  description = "Primary AWS region for the DynamoDB table."
  type        = string
  default     = "us-east-1"
}

variable "table_name" {
  description = "Name of the DynamoDB global table."
  type        = string
  default     = "example-global-dynamodb-table"
}

resource "aws_dynamodb_table" "global_table" {
  name         = var.table_name
  billing_mode = "PAY_PER_REQUEST"

